#include <bits/stdc++.h>
using namespace std;
int main() {
    long long n; string e;
    cin >> n >> e;
    vector<pair<long long,int>> terms;
    int i = 0, len = e.size(), sign = 1;
    if (len && e[0] == '-') { sign = -1; i = 1; }
    while (i < len) {
        long long coef = 1;
        int kind = 1;
        if (isdigit(e[i])) {
            coef = 0;
            while (i < len && isdigit(e[i])) coef = coef * 10 + (e[i++] - '0');
            if (i < len && e[i] == '*') i++;
        }
        if (i + 1 < len && e[i] == '+' && e[i+1] == '+') { kind = 2; i += 2; }
        if (i < len && e[i] == 'a') i++;
        if (kind != 2 && i + 1 < len && e[i] == '+' && e[i+1] == '+') i += 2;
        terms.push_back({sign * coef, kind});
        if (i < len && (e[i] == '+' || e[i] == '-')) { sign = (e[i] == '+') ? 1 : -1; i++; }
    }
    sort(terms.begin(), terms.end());
    long long total = 0;
    for (size_t p = 0; p < terms.size(); p++)
        total += terms[p].first * (n + (long long)p + (terms[p].second == 2 ? 1 : 0));
    cout << total << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
long long gcd(long long a, long long b) { return b ? gcd(b, a % b) : a; }
bool check(long long x, long long a0, long long a1, long long b0, long long b1) {
    if (x % a1) return false;
    if (gcd(x, a0) != a1) return false;
    long long g = gcd(x, b0);
    return x / g * b0 == b1;
}
int main() {
    int n; 
    scanf("%d", &n);
    while (n--) {
        long long a0, a1, b0, b1;
        scanf("%lld %lld %lld %lld", &a0, &a1, &b0, &b1);
        unsigned b = (unsigned)b1;
        unsigned lim = (unsigned)sqrt((double)b);
        while ((unsigned long long)(lim + 1) * (lim + 1) <= b) lim++;
        long long cnt = 0;
        for (unsigned d = 1; d <= lim; d++)
            if (b % d == 0) {
                if (check(d, a0, a1, b0, b1)) cnt++;
                if ((unsigned long long)d * d != b && check(b1 / d, a0, a1, b0, b1)) cnt++;
            }
        printf("%lld\n", cnt);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
double a, b, c, d;
double f(double x) { return ((a * x + b) * x + c) * x + d; }
int main() {
    cin >> a >> b >> c >> d;
    vector<double> roots;
    for (double x = -100; x < 100; x += 0.5) {
        double fx = f(x);
        if (fabs(fx) < 1e-9) roots.push_back(x);
        else if (fx * f(x + 0.5) < 0) {
            double lo = x, hi = x + 0.5;
            for (int i = 0; i < 100; i++) {
                double mid = (lo + hi) / 2;
                if (f(lo) * f(mid) <= 0) hi = mid; else lo = mid;
            }
            roots.push_back((lo + hi) / 2);
        }
    }
    if (fabs(f(100)) < 1e-9) roots.push_back(100);
    sort(roots.begin(), roots.end());
    vector<double> uniq;
    for (double r : roots) if (uniq.empty() || r - uniq.back() > 1e-6) uniq.push_back(r);
    for (size_t i = 0; i < uniq.size(); i++)
        printf("%.2f%c", uniq[i], i + 1 == uniq.size() ? '\n' : ' ');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<long long> v(n);
    for (auto &x : v) cin >> x;
    long long T;
    cin >> T;
    long long cnt = 0;
    for (long long d = 1; d < (1LL << n); d++) {
        long long s = 0;
        for (int i = 0; i < n; i++) if (d >> i & 1) s += v[i];
        if (s != T) continue;
        for (int i = 0; i < n; i++) if (d >> i & 1) cout << v[i] << ' ';
        cout << "\n";
        cnt++;
    }
    cout << cnt << endl;
    return 0;
}

